private static void renderNode(StarsEdgeConstellationVisualEntity entity, VertexConsumer vertices,
                                   MatrixStack matrices, float age, float phaseAge, float alpha) {
        float grow = easeOut(MathHelper.clamp(age / 7.0F, 0.0F, 1.0F));
        float detonationProgress = MathHelper.clamp(phaseAge / 5.0F, 0.0F, 1.0F);
        float phasePulse = entity.getPhase() == StarsEdgeConstellationVisualEntity.PHASE_DETONATE
                ? (1.0F + 1.15F * MathHelper.sin(detonationProgress * MathHelper.PI))
                * (1.0F - detonationProgress * 0.35F)
                : entity.getPhase() == StarsEdgeConstellationVisualEntity.PHASE_ARMED
                ? 1.0F + 0.12F * MathHelper.sin(phaseAge * 0.38F)
                : 1.0F + 0.06F * MathHelper.sin(age * 0.22F);
        float scale = grow * phasePulse;

        matrices.translate(0.0, 0.88 + MathHelper.sin(age * 0.10F) * 0.06F, 0.0);
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(age * 2.8F));
        matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(age * 1.35F));
        Matrix4f matrix = matrices.peek().getPositionMatrix();

        drawDiamondXY(vertices, matrix, Vec3d.ZERO, 0.42F * scale, 0.20F * scale,
                104, 35, 224, alpha(118, alpha), FULL_LIGHT);
        drawDiamondZY(vertices, matrix, Vec3d.ZERO, 0.42F * scale, 0.20F * scale,
                104, 35, 224, alpha(105, alpha), FULL_LIGHT);
        drawDiamondXY(vertices, matrix, Vec3d.ZERO, 0.29F * scale, 0.125F * scale,
                65, 230, 255, alpha(220, alpha), FULL_LIGHT);
        drawDiamondZY(vertices, matrix, Vec3d.ZERO, 0.29F * scale, 0.125F * scale,
                65, 230, 255, alpha(205, alpha), FULL_LIGHT);
        drawDiamondXY(vertices, matrix, Vec3d.ZERO, 0.13F * scale, 0.07F * scale,
                246, 250, 255, alpha(255, alpha), FULL_LIGHT);
        drawDiamondZY(vertices, matrix, Vec3d.ZERO, 0.13F * scale, 0.07F * scale,
                246, 250, 255, alpha(245, alpha), FULL_LIGHT);

        matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(-age * 3.4F));
        drawRing(vertices, matrices.peek().getPositionMatrix(), 0.52F * grow,
                0.018F, 81, 208, 255, alpha(150, alpha), FULL_LIGHT);
    }

private static void renderLink(StarsEdgeConstellationVisualEntity entity, VertexConsumer vertices,
                                   Matrix4f matrix, float age, float phaseAge, float alpha) {
        Vec3d start = new Vec3d(0.0, 0.88, 0.0);
        Vec3d offset = entity.getEndOffset();
        float grow = easeOut(MathHelper.clamp(age / 8.0F, 0.0F, 1.0F));
        Vec3d end = start.add(offset.multiply(grow));
        if (start.squaredDistanceTo(end) < 0.0001) {
            return;
        }

        float detonationProgress = MathHelper.clamp(phaseAge / 5.0F, 0.0F, 1.0F);
        float pulse = entity.getPhase() == StarsEdgeConstellationVisualEntity.PHASE_DETONATE
                ? 1.0F + 2.1F * MathHelper.sin(detonationProgress * MathHelper.PI)
                : entity.getPhase() == StarsEdgeConstellationVisualEntity.PHASE_ARMED
                ? 1.0F + 0.16F * MathHelper.sin(phaseAge * 0.45F)
                : 1.0F;
        drawCrossRibbon(vertices, matrix, start, end, 0.105F * pulse,
                91, 30, 205, alpha(105, alpha), FULL_LIGHT);
        drawCrossRibbon(vertices, matrix, start, end, 0.048F * pulse,
                63, 222, 255, alpha(205, alpha), FULL_LIGHT);
        drawCrossRibbon(vertices, matrix, start, end, 0.017F * pulse,
                244, 249, 255, alpha(245, alpha), FULL_LIGHT);

        int moteCount = Math.max(1, Math.min(4, (int) Math.ceil(offset.length() / 2.0)));
        for (int i = 0; i < moteCount; i++) {
            double progress = positiveModulo(age * 0.045F + i / (double) moteCount, 1.0);
            if (entity.getPhase() == StarsEdgeConstellationVisualEntity.PHASE_ARMED) {
                progress = positiveModulo(phaseAge * 0.075F + i / (double) moteCount, 1.0);
            }
            Vec3d mote = start.lerp(end, progress);
            float motePulse = 0.07F + 0.025F * MathHelper.sin(age * 0.4F + i * 1.7F);
            drawTinyStar(vertices, matrix, mote, motePulse,
                    226, 245, 255, alpha(235, alpha), FULL_LIGHT);
        }
    }

@Override
    public void render(T entity, float yaw, float tickDelta, MatrixStack matrices,
                       VertexConsumerProvider vertexConsumers, int light) {
        float progress = entity.getProgress();
        if (progress <= 0.0F) {
            return;
        }

        float age = entity.age + tickDelta;
        Entity owner = resolveOwner(entity);

        Vec3d offset = Vec3d.ZERO;
        float lookYaw = MathHelper.lerpAngleDegrees(tickDelta, entity.prevYaw, entity.getYaw());
        float lookPitch = 0.0F;
        float height = 1.2F;
        if (owner != null) {
            Vec3d ownerPos = new Vec3d(
                    MathHelper.lerp(tickDelta, owner.prevX, owner.getX()),
                    MathHelper.lerp(tickDelta, owner.prevY, owner.getY()),
                    MathHelper.lerp(tickDelta, owner.prevZ, owner.getZ()));
            Vec3d selfPos = new Vec3d(
                    MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                    MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                    MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));
            offset = ownerPos.subtract(selfPos);
            height = owner.getHeight() * CHEST_HEIGHT_FRACTION;
            lookYaw = MathHelper.lerpAngleDegrees(tickDelta, owner.prevYaw, owner.getYaw());
            lookPitch = MathHelper.lerp(tickDelta, owner.prevPitch, owner.getPitch());
        }

        matrices.push();
        matrices.translate(offset.x, offset.y + height, offset.z);
        // Local -Z follows the owner's look direction.
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(180.0F - lookYaw));
        matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees(-lookPitch));
        matrices.translate(0.0F, 0.0F, -FORWARD_OFFSET);

        ParchmentRendering.renderGlyphArc(matrices, vertexConsumers, entity.getGlyphStyleId(),
                entity.getGlyphBase(), entity.getGlyphCount(), progress, age, 1.35F);
        matrices.pop();

        super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
    }

private static void renderEncasement(WaxweaverWaxVisualEntity visual, MatrixStack matrices,
                                          VertexConsumerProvider providers, Sprite bone, Sprite honey,
                                          Sprite magma, float time, float tickDelta, int light) {
        Entity entity = visual.getWorld().getEntityById(visual.getTargetId());
        if (!(entity instanceof LivingEntity target)) return;

        MinecraftClient client = MinecraftClient.getInstance();
        if (target == client.player && client.options.getPerspective().isFirstPerson()) return;

        Vec3d correction = lerped(target, tickDelta).subtract(lerped(visual, tickDelta));
        matrices.translate(correction.x, correction.y, correction.z);

        float fullHeight = Math.max(0.62F, target.getHeight() + 0.28F);
        float baseRadius = Math.max(0.58F, target.getWidth() * 0.72F + 0.23F);
        float formation = smooth(MathHelper.clamp(time / WaxweaverEncasementManager.FORMATION_TICKS, 0.0F, 1.0F));
        float shownHeight = Math.max(0.045F, fullHeight * formation);
        float remaining = visual.getLifetime() - time;
        float warning = smooth(MathHelper.clamp((20.0F - remaining) / 20.0F, 0.0F, 1.0F));
        float shudder = warning * warning * 0.025F;
        if (shudder > 0.0F) {
            matrices.translate(MathHelper.sin(time * 3.7F + visual.getSeed() * 0.013F) * shudder,
                    MathHelper.sin(time * 5.1F) * shudder * 0.35F,
                    MathHelper.cos(time * 4.3F + visual.getSeed() * 0.009F) * shudder);
        }

        int waxLight = Math.max(light, 0x00C000C0);
        VertexConsumer solid = providers.getBuffer(RenderLayer.getEntityCutout(SpriteAtlasTexture.BLOCK_ATLAS_TEXTURE));
        drawFootMound(solid, matrices.peek(), bone, visual.getSeed(), baseRadius,
                MathHelper.clamp(time / 2.8F, 0.0F, 1.0F), waxLight);
        drawCoreShell(solid, matrices.peek(), bone, visual.getSeed(), baseRadius,
                fullHeight, shownHeight, waxLight);
        drawLayeredPlates(solid, matrices.peek(), bone, visual.getSeed(), baseRadius,
                fullHeight, time, waxLight);

        float seal = smooth(MathHelper.clamp((time - 7.2F) / 2.8F, 0.0F, 1.0F));
        if (seal > 0.0F) {
            drawHardenedDrips(solid, matrices, bone, visual.getSeed(), baseRadius,
                    fullHeight, seal, waxLight);
            drawWick(solid, matrices, bone, fullHeight, seal, waxLight);

            VertexConsumer translucent = providers.getBuffer(RenderLayer.getTranslucentMovingBlock());
            drawSeams(translucent, matrices, honey, visual.getSeed(), baseRadius,
                    fullHeight, seal, warning, Math.max(light, 0x00D000D0), false);
            if (warning > 0.025F) {
                VertexConsumer emissive = providers.getBuffer(
                        RenderLayer.getEntityTranslucentEmissive(SpriteAtlasTexture.BLOCK_ATLAS_TEXTURE));
                drawSeams(emissive, matrices, magma, visual.getSeed(), baseRadius,
                        fullHeight, seal, warning, FULL_LIGHT, true);
            }
        }
    }

@Override
    public void render(RiftmaneRiftVisualEntity entity, float yaw, float tickDelta,
                       MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        if (IrisCompat.isRenderingShadowPass() || !Config.general.enableModernFieldEffects) {
            return;
        }

        float age = entity.age + tickDelta;
        float remaining = entity.getLifetime() - age;
        float open = RiftmaneRenderGeometry.easeOutBack(MathHelper.clamp(age / OPEN_TICKS, 0.0F, 1.0F));
        float close = MathHelper.clamp(remaining / CLOSE_TICKS, 0.0F, 1.0F);
        float widthScale = open * MathHelper.clamp(close * 1.7F, 0.0F, 1.0F);
        float heightScale = open * close;
        boolean lensVisible = widthScale >= 0.01F && heightScale >= 0.01F;
        float ringProgress = MathHelper.clamp(
                (age - (entity.getLifetime() - SLAM_RING_TICKS)) / SLAM_RING_TICKS, 0.0F, 1.0F);
        boolean ringVisible = ringProgress > 0.0F && ringProgress < 1.0F;
        if (!lensVisible && !ringVisible) {
            return;
        }

        float height = entity.getRiftHeight();
        double halfHeight = height * 0.5 * heightScale;
        double halfWidth = height * HALF_WIDTH_RATIO * widthScale;
        double centerY = height * 0.5;
        int seed = entity.getSeed();
        float wobblePhase = age * 0.35F + seed;

        matrices.push();
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-entity.getYaw()));
        Matrix4f matrix = matrices.peek().getPositionMatrix();

        if (lensVisible) {
            VertexConsumer core = vertexConsumers.getBuffer(RenderLayer.getEntityTranslucent(WHITE_TEXTURE));
            RiftmaneRenderGeometry.lensFill(core, matrix, LENS_SEGMENTS, centerY, halfWidth, halfHeight,
                    4, 8, 14, 235, 120);
        }

        VertexConsumer glow = vertexConsumers.getBuffer(RenderLayer.getEntityTranslucentEmissive(WHITE_TEXTURE));
        if (lensVisible) {
            RiftmaneRenderGeometry.lensRim(glow, matrix, LENS_SEGMENTS, centerY, halfWidth, halfHeight,
                    0.14 + 0.05 * MathHelper.sin(wobblePhase * 1.7F), 0.45F, wobblePhase,
                    150, 255, 246, 230, 0);
            RiftmaneRenderGeometry.lensRim(glow, matrix, LENS_SEGMENTS, centerY, halfWidth, halfHeight,
                    0.05, 0.2F, wobblePhase * 1.4F, 226, 255, 252, 255, 90);
            drawLightColumn(glow, matrix, height, halfWidth, heightScale, wobblePhase);
        }
        if (ringVisible) {
            drawSlamRing(glow, matrix, ringProgress);
        }

        if (lensVisible) {
            VertexConsumer arcs = vertexConsumers.getBuffer(LightningRenderLayers.BLOCKY_LIGHTNING);
            drawRimArcs(arcs, matrix, centerY, halfWidth, halfHeight, seed, age, heightScale);
        }

        matrices.pop();
        super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
    }
